def transform(grid):
    """Fill interiors of hollow rectangular frames; 6-frame interior uses 2,
    and 4-frame interior uses 7."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (9, 2, 7) or (r, c) in seen:
                continue
            # Find component of this non-background color.
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            # A complete rectangular border encloses the target fill color.
            if all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0,c1+1)) and all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0,r1+1)):
                fill = {6: 2, 4: 7}.get(color, color)
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if grid[y][x] == 9:
                            out[y][x] = fill
    return out

